INSERT INTO learning_skills(code,title,description) VALUES('python.values','Переменные и типы данных','Прослеживать присваивания и отличать число, строку и логическое значение.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: предскажи значение, затем проверь

**После урока ты сможешь** проследить изменение переменной, различить `str`, `int`, `float`, `bool` и объяснить, почему одинаково выглядящие значения ведут себя по-разному.

| Выражение | Значение | Тип |
| --- | --- | --- |
| `7 + 2` | `9` | `int` |
| `"7" + "2"` | `"72"` | `str` |
| `7 / 2` | `3.5` | `float` |
| `7 > 2` | `True` | `bool` |

```python
score = 4
saved = score
score = score + 3
print(score, saved)  # 7 4
```

Присваивание не устанавливает вечную связь между именами. Здесь `saved` продолжает обозначать число 4. Справа от `=` сначала вычисляется выражение, затем результат связывается с именем слева.

**Типичная ошибка:** считать `"False"` логической ложью. Это непустая строка, а не значение `False`. В частности, `bool("False")` даёт `True`.

### Самопроверка без запуска

После `x = 8; y = x; x = 1` чему равны `x` и `y`? Почему `"3" * 2` и `3 * 2` дают разные результаты?

**Разбор:** `x` равен 1, `y` равен 8; повторение строки даёт `"33"`, числовое умножение — 6. Запусти примеры в Python 3 и сравни с прогнозом. Умение объяснить расхождение полезнее угадывания вывода.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Python: основы программирования','Python с ИИ: основы программирования') AND p.type='theory' AND p.title='Переменные и типы данных';

