DECLARE section_id_value BIGINT; target_position INTEGER; page_id_value BIGINT; test_id_value BIGINT; question_id_value BIGINT; item RECORD; q JSONB;
BEGIN
 FOR section_id_value IN SELECT s.id FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.title='Python: основы программирования' AND s.title='Основы Python' LOOP
  SELECT p.position+1 INTO target_position FROM course_pages p WHERE p.section_id=section_id_value AND p.type='test' AND NOT EXISTS(SELECT 1 FROM tests t JOIN assessment_definitions d ON d.test_id=t.id WHERE t.page_id=p.id) ORDER BY p.position DESC LIMIT 1;
  IF target_position IS NULL THEN RAISE EXCEPTION 'Missing ordinary section check'; END IF;
  -- Move later pages in descending order to respect the immediate unique position constraint.
  FOR item IN SELECT id,position FROM course_pages WHERE section_id=section_id_value AND position>=target_position ORDER BY position DESC LOOP
   UPDATE course_pages SET position=item.position+1 WHERE id=item.id;
  END LOOP;
  INSERT INTO course_pages(section_id,title,type,content,position) VALUES(section_id_value,'Самостоятельная практика: Основы Python','test',NULL,target_position) RETURNING id INTO page_id_value;
  INSERT INTO course_upgrade_v10_added_pages VALUES(page_id_value);
  INSERT INTO tests(page_id,passing_score) VALUES(page_id_value,60) RETURNING id INTO test_id_value;
  FOR q IN SELECT value FROM jsonb_array_elements('[{"question": "После x = 8; y = x; x = 1 какое значение хранит y?", "options": ["Имя y удаляется", "8", "1", "9"], "correct_index": 1, "position": 0}, {"question": "Какой результат даёт \"3\" * 2 в Python 3?", "options": ["Строку \"6\"", "Всегда ошибку типа", "Строку \"33\"", "Число 6"], "correct_index": 2, "position": 1}, {"question": "Почему bool(\"False\") возвращает True?", "options": ["Python распознаёт английское слово как ложь", "Все строки ложны", "bool возвращает текст, а не логическое значение", "Любая непустая строка истинна в логическом контексте"], "correct_index": 3, "position": 2}, {"question": "Пользователь ввёл 12. Что хранит x сразу после x = input()?", "options": ["Логическое True", "Строку \"12\"", "Целое число 12", "Число 12.0"], "correct_index": 1, "position": 3}, {"question": "Как найти оставшиеся минуты при переводе 137 минут в часы?", "options": ["137 % 60", "137 / 60", "137 // 60", "60 % 137"], "correct_index": 0, "position": 4}, {"question": "Как преобразовать строку \"3.5\" в дробное число?", "options": ["bool(\"3.5\")", "float(\"3.5\")", "int(\"3.5\")", "str(\"3.5\")"], "correct_index": 1, "position": 5}]'::jsonb) LOOP
   INSERT INTO test_questions(test_id,question,position) VALUES(test_id_value,q->>'question',(q->>'position')::integer) RETURNING id INTO question_id_value;
   INSERT INTO test_answers(question_id,text,is_correct,position)
   SELECT question_id_value,value,(ordinality-1)=(q->>'correct_index')::integer,ordinality-1 FROM jsonb_array_elements_text(q->'options') WITH ORDINALITY;
  END LOOP;
 END LOOP;
END $upgrade$;

