DECLARE section_id_value BIGINT; target_position INTEGER; page_id_value BIGINT; test_id_value BIGINT; question_id_value BIGINT; item RECORD; q JSONB;
BEGIN
 FOR section_id_value IN SELECT s.id FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.title='Python: основы программирования' AND s.title='Коллекции и функции' LOOP
  SELECT p.position+1 INTO target_position FROM course_pages p WHERE p.section_id=section_id_value AND p.type='test' AND NOT EXISTS(SELECT 1 FROM tests t JOIN assessment_definitions d ON d.test_id=t.id WHERE t.page_id=p.id) ORDER BY p.position DESC LIMIT 1;
  IF target_position IS NULL THEN RAISE EXCEPTION 'Missing ordinary section check'; END IF;
  -- Move later pages in descending order to respect the immediate unique position constraint.
  FOR item IN SELECT id,position FROM course_pages WHERE section_id=section_id_value AND position>=target_position ORDER BY position DESC LOOP
   UPDATE course_pages SET position=item.position+1 WHERE id=item.id;
  END LOOP;
  INSERT INTO course_pages(section_id,title,type,content,position) VALUES(section_id_value,'Самостоятельная практика: Коллекции и функции','test',NULL,target_position) RETURNING id INTO page_id_value;
  INSERT INTO course_upgrade_v10_added_pages VALUES(page_id_value);
  INSERT INTO tests(page_id,passing_score) VALUES(page_id_value,60) RETURNING id INTO test_id_value;
  FOR q IN SELECT value FROM jsonb_array_elements('[{"question": "Что означает items[1] для списка [10, 20, 30]?", "options": ["20", "10", "30", "Длину списка"], "correct_index": 0, "position": 0}, {"question": "После a = [1]; b = a; a.append(2) чему равно b?", "options": ["[1]", "[2]", "None", "[1, 2]"], "correct_index": 3, "position": 1}, {"question": "Какая структура удобнее хранит цену по названию товара?", "options": ["Одно логическое значение", "Список цен без связи с названиями", "Словарь с названиями как ключами", "Одна строка со всеми ценами"], "correct_index": 2, "position": 2}, {"question": "Что возвращает функция, которая только вызывает print(x * 2) и не выполняет return?", "options": ["None", "Всегда число x * 2", "Строку с напечатанным числом", "Саму функцию print"], "correct_index": 0, "position": 3}, {"question": "Для discount(200, 15) с return price * (100 - percent) / 100 какой результат?", "options": ["215", "170.0", "185", "30"], "correct_index": 1, "position": 4}, {"question": "Зачем в is_even(n) писать return n % 2 == 0?", "options": ["Чтобы изменить n во всей программе", "Чтобы запретить вызов функции из условия", "Чтобы вызывающий код получил логический результат", "Чтобы обязательно напечатать n"], "correct_index": 2, "position": 5}]'::jsonb) LOOP
   INSERT INTO test_questions(test_id,question,position) VALUES(test_id_value,q->>'question',(q->>'position')::integer) RETURNING id INTO question_id_value;
   INSERT INTO test_answers(question_id,text,is_correct,position)
   SELECT question_id_value,value,(ordinality-1)=(q->>'correct_index')::integer,ordinality-1 FROM jsonb_array_elements_text(q->'options') WITH ORDINALITY;
  END LOOP;
 END LOOP;
END $upgrade$;

