INSERT INTO course_upgrade_v10_original_pages SELECT p.id,p.content,p.position,p.updated_at FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Основы психологии','Основы психологии с ИИ');

INSERT INTO learning_skills(code,title,description) VALUES('psychology.attention','Внимание и восприятие','Отделять наблюдение от интерпретации и учитывать ограничения внимания.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: наблюдение ещё не объяснение

**Цель:** различать наблюдаемый факт и вывод о нём, учитывать избирательность внимания.

Ситуация: однокурсник прошёл мимо и не поздоровался. **Наблюдение:** он прошёл, приветствия не было. **Интерпретация:** «он меня презирает». Есть и другие гипотезы: не заметил, был погружён в разговор, торопился. По одному эпизоду намерение не установлено.

| Утверждение | Статус |
| --- | --- |
| Он не ответил на приветствие | Описание доступного наблюдения |
| Он хотел меня унизить | Гипотеза о намерении |
| Нужно уточнить, услышал ли он | Способ получить дополнительные данные |

### Ограниченное внимание

Попробуй читать абзац и одновременно считать каждую букву «а». Две задачи конкурируют за ресурсы; субъективное ощущение «я всё контролирую» не гарантирует качества выполнения. Это учебная демонстрация, не диагностика внимания.

**Типичная ошибка:** считать пропуск детали доказательством плохих способностей или лжи. Условия задачи, усталость, отвлечение и ожидания тоже влияют на замеченное. Восприятие активно организует информацию, но это не значит, что любые факты произвольны.

### Самопроверка

«Он посмотрел на часы, значит, ему скучно». Где наблюдение? **Ответ:** взгляд на часы. «Скучно» — возможное объяснение, которому нужны дополнительные основания. Сформулируй ещё два объяснения, прежде чем выбирать одно.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Внимание и восприятие';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'psychology.attention' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Внимание и восприятие';

INSERT INTO learning_skills(code,title,description) VALUES('psychology.memory','Память и обучение','Планировать извлечение, интервальные повторы и проверку точности.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: проверяй воспроизведение

**Цель:** отличать узнавание текста от самостоятельного ответа и спланировать повторение.

Два ученика читают один материал. Первый перечитывает его пять раз подряд. Второй закрывает текст, отвечает на вопросы, сверяется, а затем возвращается к трудным вопросам на следующий день. Второй способ включает **извлечение** и распределение практики во времени. Это полезные приёмы, но результат также зависит от материала и обратной связи.

![Учебный цикл: вспомнить → проверить → исправить → повторить позже](/images/psychology-retrieval-cycle.svg)

### Пример плана

| Когда | Действие | Что записать |
| --- | --- | --- |
| После урока | Ответить без конспекта | Ошибки и пропуски |
| Завтра | Повторить трудные вопросы | Что исправилось |
| Через несколько дней | Новые примеры на тот же принцип | Перенос знания |

**Разбор ошибки:** «Я уверенно узнаю страницу, значит, умею применять правило». Узнавание знакомого оформления не равно решению новой задачи. Проверяй и объяснение, и применение.

Память реконструктивна: новая информация и формулировка вопроса могут влиять на воспоминание. Уверенность сама по себе не устанавливает точность.

### Самопроверка

Закрой этот урок и назови два различия между перечитыванием и извлечением. **Ответ:** при извлечении ответ восстанавливается без подсказки; проверка выявляет реальные пробелы, которые можно целенаправленно исправить.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Память и обучение';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'psychology.memory' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Память и обучение';

INSERT INTO learning_skills(code,title,description) VALUES('psychology.emotion','Эмоции и стресс','Различать событие, оценку и реакцию и выбирать посильное действие.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: событие → оценка → действие

**Цель:** замечать эмоциональную реакцию и не принимать её автоматически за доказательство чужих намерений.

Ситуация: преподаватель предлагает переделать работу. Мысль «я ни на что не способен» вызывает один отклик; мысль «есть конкретные недочёты, которые можно уточнить» — другой. Это не означает, что эмоции нужно запретить: они дают информацию о состоянии и значимости ситуации.

| Шаг | Пример |
| --- | --- |
| Факт | В работе попросили исправить два пункта |
| Автоматическая оценка | «Любая ошибка означает провал» |
| Проверка | Какие именно пункты и критерии? |
| Действие | Уточнить требования и исправить один пункт |

### Разбор типичной ловушки

«Мне страшно, значит, ситуация обязательно опасна» смешивает чувство и оценку внешней угрозы. Эмоцию можно признать, а факты проверить отдельно. Реальные риски при этом нельзя игнорировать.

Краткая пауза, снижение лишней нагрузки, сон и поддержка могут помочь справляться с напряжением. Ни один такой приём не является универсальным лечением. Устойчивые трудности, мешающие повседневной жизни, — повод обратиться за профессиональной поддержкой.

### Самопроверка

Предложи вопрос вместо фразы «Вы специально занизили оценку». **Вариант:** «Помогите понять, какие критерии я не выполнил и что исправить». Он позволяет получить данные, не выдавая догадку за установленное намерение.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Эмоции и стресс';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'psychology.emotion' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Эмоции и стресс';

INSERT INTO learning_skills(code,title,description) VALUES('psychology.bias','Мышление и когнитивные искажения','Узнавать смещения в конкретном выводе и искать недостающие данные.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: какие данные мы не увидели

**Цель:** проверять ход рассуждения, а не навешивать на собеседника ярлык «искажение».

В рекламе курса показывают десять выпускников, нашедших работу. Сколько всего училось? Сколько не ответили? Какими были их навыки до курса? Без этих данных нельзя оценить вероятность трудоустройства или причинный эффект обучения.

| Смещение | Пример | Проверочный вопрос |
| --- | --- | --- |
| Подтверждающее | Читаю только отзывы в пользу своего решения | Что могло бы опровергнуть вывод? |
| Ошибка выжившего | Вижу только успешных выпускников | Какие случаи отобраны и исключены? |
| Якорь | Первая цена меняет оценку скидки | С чем ещё можно сравнить цену? |

### Корреляция и причина

Люди, которые больше практикуются, могут получать выше баллы. Но на оба показателя могут влиять исходные знания, мотивация и доступное время. Связь важна, однако её одной недостаточно для причинного вывода.

**Разбор ошибки:** название эффекта не заменяет объяснения. Нужно показать, какой именно отбор или ход мысли исказил вывод, и предложить способ проверки. Люди подвержены смещениям, но это не делает каждое их решение ошибочным.

### Самопроверка

К исследованию добавили только студентов, завершивших курс. Какой вопрос стоит задать? **Ответ:** чем выбывшие отличаются от оставшихся и как это изменило оценку. Пропущенные результаты нельзя без объяснения считать нулевыми или успешными.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Мышление и когнитивные искажения';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'psychology.bias' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Мышление и когнитивные искажения';

INSERT INTO learning_skills(code,title,description) VALUES('psychology.personality','Личность и индивидуальные различия','Различать черту, состояние и качество измерения.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: тенденция не предсказание каждого поступка

**Цель:** отличать устойчивые различия от ситуативного состояния и оценивать измерительный инструмент.

Мира обычно общительна, но после бессонной ночи молчит на встрече. Один эпизод не отменяет устойчивую тенденцию и не позволяет объявить её «другим типом». На поведение влияют и особенности человека, и обстоятельства.

Модель «Большой пятёрки» описывает широкие измерения черт, а не пять взаимоисключающих коробок. У человека есть положение на каждом измерении; высокий показатель не является сам по себе диагнозом, заслугой или недостатком.

| Понятие | Вопрос |
| --- | --- |
| Черта | Какова относительно устойчивая тенденция? |
| Состояние | Что происходит в данный момент? |
| Надёжность | Насколько измерение согласованно при соответствующих условиях? |
| Валидность | Обоснованно ли нужное толкование результата? |

**Разбор:** тест может стабильно выдавать один результат и всё же плохо измерять заявленное свойство. Надёжность важна, но сама по себе не доказывает валидность. Тест по любимому цвету не становится научным из-за красивого графика.

### Самопроверка

Можно ли по одному ответу в чате установить личность человека? **Нет:** контекст и случайные факторы слишком значимы. Для обоснованного вывода нужны подходящий инструмент, несколько наблюдений и ясные границы интерпретации.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Основы психологии','Основы психологии с ИИ') AND p.type='theory' AND p.title='Личность и индивидуальные различия';

