  FOR q IN SELECT value FROM jsonb_array_elements('[{"question": "Какой вопрос лучше соответствует аллегории пещеры?", "options": ["Почему собственные убеждения не нуждаются в проверке?", "Как условия наблюдения ограничивают представление о реальности?", "Почему любое чужое мнение обязательно ложно?", "Как одним образом доказать существование компьютерной симуляции?"], "correct_index": 1, "position": 0}, {"question": "Лента показывает только короткие фрагменты конфликта. Какой шаг улучшает обоснованность вывода?", "options": ["Найти полный контекст и независимые свидетельства", "Считать число просмотров доказательством полноты", "Объявить ложным каждый кадр без проверки", "Назвать всех несогласных узниками пещеры"], "correct_index": 0, "position": 1}, {"question": "Что не следует автоматически из аллегории?", "options": ["Что доступный образ может быть ограниченным", "Что обучение может менять привычную картину мира", "Что конкретная гипотеза о симуляции доказана", "Что полезно проверять основания убеждений"], "correct_index": 2, "position": 2}, {"question": "Из того, что сценарий «мозг в сосуде» можно вообразить, следует ли, что он реален?", "options": ["Да, если его трудно опровергнуть", "Нет, потому что мысленные эксперименты запрещены", "Нет, логическая возможность не является эмпирическим подтверждением", "Да, любой воображаемый сценарий реализован"], "correct_index": 2, "position": 3}, {"question": "Что ошибочно в доводе «Меня не опровергли, значит, мой тезис доказан»?", "options": ["Опровергать можно только числовые утверждения", "Отсутствие опровержения подменяет положительное обоснование", "Тезисы не нуждаются в основаниях", "Любой неопровергнутый тезис автоматически ложен"], "correct_index": 1, "position": 4}, {"question": "Какой подход совместим с обоснованным, но пересматриваемым знанием?", "options": ["Принимать все возможные гипотезы одновременно как факты", "Проверять методы и независимые данные, допуская исправление вывода", "Считать личную уверенность абсолютной гарантией", "Отвергать любые данные заранее"], "correct_index": 1, "position": 5}]'::jsonb) LOOP
   INSERT INTO test_questions(test_id,question,position) VALUES(test_id_value,q->>'question',(q->>'position')::integer) RETURNING id INTO question_id_value;
   INSERT INTO test_answers(question_id,text,is_correct,position)
   SELECT question_id_value,value,(ordinality-1)=(q->>'correct_index')::integer,ordinality-1 FROM jsonb_array_elements_text(q->'options') WITH ORDINALITY;
  END LOOP;
 END LOOP;
END $upgrade$;

DO $upgrade$
DECLARE section_id_value BIGINT; target_position INTEGER; page_id_value BIGINT; test_id_value BIGINT; question_id_value BIGINT; item RECORD; q JSONB;
BEGIN
 FOR section_id_value IN SELECT s.id FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE c.title='Философия без занудства' AND s.title='Этика, свобода и хорошая жизнь' LOOP
  SELECT p.position+1 INTO target_position FROM course_pages p WHERE p.section_id=section_id_value AND p.type='test' AND NOT EXISTS(SELECT 1 FROM tests t JOIN assessment_definitions d ON d.test_id=t.id WHERE t.page_id=p.id) ORDER BY p.position DESC LIMIT 1;
  IF target_position IS NULL THEN RAISE EXCEPTION 'Missing ordinary section check'; END IF;
  -- Move later pages in descending order to respect the immediate unique position constraint.
  FOR item IN SELECT id,position FROM course_pages WHERE section_id=section_id_value AND position>=target_position ORDER BY position DESC LOOP
   UPDATE course_pages SET position=item.position+1 WHERE id=item.id;
  END LOOP;
  INSERT INTO course_pages(section_id,title,type,content,position) VALUES(section_id_value,'Самостоятельная практика: Этика, свобода и хорошая жизнь','test',NULL,target_position) RETURNING id INTO page_id_value;
  INSERT INTO course_upgrade_v10_added_pages VALUES(page_id_value);
  INSERT INTO tests(page_id,passing_score) VALUES(page_id_value,60) RETURNING id INTO test_id_value;
  FOR q IN SELECT value FROM jsonb_array_elements('[{"question": "Какой вопрос прежде всего рассматривает утилитарный аргумент?", "options": ["Только личную выгоду действующего", "Только соблюдение любой команды", "Только репутацию в социальных сетях", "Последствия для благополучия затронутых людей"], "correct_index": 3, "position": 0}, {"question": "Аргумент «Ложное обещание нарушает обязанность» прежде всего опирается на что?", "options": ["На число лайков", "На личную выгоду", "На случайный выбор", "На долг и обязательства"], "correct_index": 3, "position": 1}, {"question": "Почему один ответ на задачу о вагонетке не устанавливает всю моральную теорию человека?", "options": ["Достаточно знать только скорость вагонетки", "Одинаковый ответ может иметь разные основания и зависеть от условий", "Все ответы означают одну и ту же теорию", "Моральные аргументы не имеют оснований"], "correct_index": 1, "position": 2}, {"question": "Чем закрытая дверь отличается от спора о детерминизме?", "options": ["Оба выражения всегда означают одно и то же", "Дверь устанавливает любую теорию ответственности", "Это конкретное внешнее ограничение, которое само по себе не решает спор о причинной обусловленности выбора", "Закрытая дверь доказывает, что причин нет"], "correct_index": 2, "position": 3}, {"question": "Что означает вопрос о совместимости свободы и детерминизма?", "options": ["Есть ли в комнате физическая дверь", "Можно ли избежать любого влияния среды", "Верны ли все решения большинства", "Можно ли содержательно говорить о свободе при причинной обусловленности"], "correct_index": 3, "position": 4}, {"question": "Почему из наличия причин поступка не следует автоматически полное отсутствие ответственности?", "options": ["Любая причина является оправданием", "Достаточно заменить объяснение цитатой", "Нужны дополнительные посылки о связи свободы, причин и ответственности", "Ответственность вообще не обсуждается в философии"], "correct_index": 2, "position": 5}]'::jsonb) LOOP
   INSERT INTO test_questions(test_id,question,position) VALUES(test_id_value,q->>'question',(q->>'position')::integer) RETURNING id INTO question_id_value;
   INSERT INTO test_answers(question_id,text,is_correct,position)
   SELECT question_id_value,value,(ordinality-1)=(q->>'correct_index')::integer,ordinality-1 FROM jsonb_array_elements_text(q->'options') WITH ORDINALITY;
  END LOOP;
 END LOOP;
END $upgrade$;

INSERT INTO course_upgrade_v10_original_pages SELECT p.id,p.content,p.position,p.updated_at FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов');

INSERT INTO learning_skills(code,title,description) VALUES('memology.history','До интернета: мемы как культурные репликаторы','Различать культурную передачу, отдельное изображение и семейство вариантов.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: картинка ещё не вся история

**Цель:** отличать исходный материал, узнаваемый шаблон и конкретную публикацию.

Термин «мем» предложен Ричардом Докинзом в книге «Эгоистичный ген» (1976) для обсуждения культурной передачи. Это шире современных картинок с подписью. Аналогия с репликатором не означает, что любая шутка распространяется строго как биологический ген.

| Уровень | Пример |
| --- | --- |
| Исходный материал | Фотография собаки Кабосу |
| Шаблон | Узнаваемый образ Doge |
| Вариант | Публикация с конкретными подписями |
| Практика сообщества | Способ совместно шутить на этом языке |

![Doge: настоящая фотографическая основа шаблона с собакой Кабосу, без добавленных нами подписей](/images/memes/doge.jpg)

Фотография связана с Ацуко Сато и её собакой Кабосу; известный снимок опубликован в 2010 году. Языковая игра в вариантах Doge — короткие эмоциональные фразы и намеренно необычная английская грамматика. Фотография сама по себе и последующее семейство подписей — разные исторические объекты.

### Как описывать происхождение

Разделяй дату создания исходного материала, раннюю найденную публикацию варианта и период массовой популярности. «Самая ранняя найденная» не всегда означает «самая первая в мире». Карикатуры, анекдоты и лозунги показывают культурную передачу до интернета, но не являются тем же самым платформенным форматом.

### Самопроверка

Считается ли каждый репост новой мутацией? **Нет:** повторная публикация без смыслового изменения и переработка — разные операции.

[Справка о Doge и происхождении фотографии](https://knowyourmeme.com/memes/doge). Локальная копия настоящего шаблона взята из [каталога memegen](https://github.com/jacebrowning/memegen/tree/main/templates/doge); изображение не сгенерировано ИИ.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='До интернета: мемы как культурные репликаторы';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'memology.history' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='До интернета: мемы как культурные репликаторы';

INSERT INTO learning_skills(code,title,description) VALUES('memology.formats','Ранний интернет и культура шаблонов','Распознавать повторяемую структуру и отличать её от конкретного сюжета.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: узнаваемость плюс замена

**Цель:** находить устойчивую структуру формата и объяснять, что меняется между вариантами.

Ранний интернет распространял шутки через форумы, письма, блоги и имиджборды. Позже платформы ускорили обмен, но не отменили роли локальных сообществ. Хронология не является лестницей, на которой каждый новый формат уничтожает предыдущий.

![Кадр с Баззом и Вуди из «Истории игрушек», используемый как основа формата «X, X повсюду»](/images/memes/buzz-and-woody.jpg)

В этом реальном шаблоне Базз указывает вдаль, а Вуди смотрит перед собой. В вариантах «X, X повсюду» подпись представляет некоторое явление как повсеместное. Кадр из фильма — исходный материал, а распространённая подпись не является автоматически дословной репликой из этой сцены.

### Сравниваем формы

| Формат | Что повторяется | Что можно заменить |
| --- | --- | --- |
| Изображение-макрос | Картинка и расположение надписей | Ситуация и панчлайн |
| Комикс | Порядок кадров и роли | Реплики и детали |
| Короткое видео | Звук, жест или монтажный ритм | Участник и сюжет |

**Ловушка:** считать мемом только статическую картинку. Звук или жест тоже могут задавать воспроизводимый шаблон. Но вирусный ролик без устойчивых переработок и семейство мемных вариантов — не обязательно одно и то же.

### Самопроверка

Два ролика используют один звук, но показывают разные ситуации. Что в них инвариантно? **Ответ:** узнаваемая аудиоструктура; конкретный сюжет изменён. Для анализа нужны оба уровня.

Источник изображения: Disney/Pixar, «История игрушек»; [каталог шаблона](https://github.com/jacebrowning/memegen/tree/main/templates/buzz), [пример семейства](https://imgflip.com/memetemplate/X-Everywhere). Это подлинный кадр, а не наша перерисовка.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='Ранний интернет и культура шаблонов';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'memology.formats' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='Ранний интернет и культура шаблонов';

INSERT INTO learning_skills(code,title,description) VALUES('memology.mechanism','Шаблон, ожидание и панчлайн','Объяснять роли, контраст и зависимость шутки от контекста.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: разбираем Distracted Boyfriend

**Цель:** объяснять механизм шутки через роли и противоречие ожиданию, а не через фразу «смешно, потому что мем».

![Distracted Boyfriend: настоящая фотография-шаблон — мужчина оборачивается на прохожую, его спутница недовольна](/images/memes/distracted-boyfriend.jpg)

Исходная постановочная стоковая фотография Антонио Гиллема снята в 2015 году; широкая мемная популярность пришла позже. В учебном разборе роли можно обозначить словами: **ученик**, **запланированная подготовка**, **ещё одно видео**. Мы не выдаём эти учебные подписи за исторически первый вариант.

| Роль в изображении | Учебная интерпретация |
| --- | --- |
| Отвлёкшийся человек | Ученик |
| Недовольная спутница | Намеченная подготовка |
| Новая привлекательная цель | Ещё одно видео |

Юмор возникает из узнаваемого конфликта между заявленным намерением и переключением внимания. Если зритель не понимает, что обозначают подписи, само наличие известной картинки не гарантирует шутки.

### Разбор ошибки

«Мем доказывает, что все ученики ленивы» — неоправданное обобщение. Шаблон подчёркивает отношение и оценку автора публикации, а не измеряет распространённость поведения. Изображение нельзя использовать как психологическое доказательство о людях на фотографии.

### Самопроверка

Что произойдёт, если поменять местами «подготовку» и «видео»? **Ответ:** отношение между соблазном и оставленной целью перевернётся, поэтому изменится смысл варианта.

[История формата и автор исходной фотографии](https://knowyourmeme.com/memes/distracted-boyfriend); [источник локальной копии шаблона](https://github.com/jacebrowning/memegen/tree/main/templates/db). Использовано настоящее изображение без добавленной нами генерации или ретуши.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='Шаблон, ожидание и панчлайн';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'memology.mechanism' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='Шаблон, ожидание и панчлайн';

INSERT INTO learning_skills(code,title,description) VALUES('memology.remix','Ремикс, интертекст и мутация','Сравнивать варианты по смысловым изменениям и культурным отсылкам.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: Drakeposting и смена оценки

**Цель:** отличать исходный кадр, рамку одобрения и новую смысловую подстановку.

![Drakeposting: реальные кадры с Дрейком — жест отказа сверху и одобрения снизу](/images/memes/drake.png)

Кадры связаны с клипом Дрейка «Hotline Bling» (2015). В распространённой двухчастной конструкции верхняя половина отвергает один вариант, нижняя одобряет другой. Это мемное чтение жестов; оно не означает, что Дрейк действительно высказывался о каждой добавленной теме.

Учебный вариант словами: сверху «пять раз перечитать», снизу «вспомнить без подсказки и проверить». Автор меняет предмет оценки, сохраняя структуру «нет / да».

### Где начинается переработка

| Изменение | Аналитическое описание |
| --- | --- |
| Только пересохранить файл | Техническое изменение, не обязательно новая шутка |
| Заменить подписи | Новая тема в знакомой структуре |
| Поменять порядок одобрения | Возможное обращение исходной оценки |
| Соединить с другим мемом | Интертекст: смысл зависит от двух источников |

**Ловушка:** считать любой вариант независимым от контекста. Ироническая публикация может внешне одобрять то, что автор на деле высмеивает; без окружающего разговора вывод об авторской позиции может быть ненадёжен.

### Самопроверка

Можно ли по шаблону заключить, что артист рекламирует учебную методику? **Нет:** добавленная чужим автором подпись не создаёт такого свидетельства. Разделяй героя изображения и автора публикации.

[История Drakeposting](https://knowyourmeme.com/memes/drakeposting); [локальная копия подлинного шаблона](https://github.com/jacebrowning/memegen/tree/main/templates/drake). Кадры не сгенерированы нами.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='Ремикс, интертекст и мутация';

INSERT INTO page_learning_skills(page_id,skill_code) SELECT p.id,'memology.remix' FROM course_pages p JOIN course_sections s ON s.id=p.section_id JOIN courses c ON c.id=s.course_id WHERE c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='Ремикс, интертекст и мутация';

INSERT INTO learning_skills(code,title,description) VALUES('memology.community','Мемы как социальный язык','Учитывать аудиторию, позицию публикации и границы допустимого вывода.');

UPDATE course_pages p SET content=coalesce(p.content,'') || E'\n\n---\n\n' || '## Практикум: «This is fine» в разных разговорах

**Цель:** различать содержание изображения, позицию автора публикации и возможное чтение аудиторией.

![This is fine: подлинный фрагмент комикса KC Green — собака с чашкой среди огня; здесь показана основа без речевого облака](/images/memes/this-is-fine-crop.png)

Источник — комикс **KC Green**, Gunshow №648 (2013). Показан распространённый кадр-шаблон, а не полная оригинальная полоса: речевое облако в этой копии отсутствует. Название формата «This is fine» переводится как «Всё в порядке»; контраст с пожаром делает возможным чтение как отрицания очевидной проблемы.

В чате разработчиков перед релизом такой образ может означать самоиронию. В сообщении о реальной чрезвычайной ситуации тот же формат могут воспринять как обесценивание. Значение зависит от темы, отношений и ситуации; нельзя гарантировать одну реакцию всех зрителей.

### Карта анализа

1. Кто публикует и кому?
2. Что произошло в окружающем разговоре?
3. Над чем направлена шутка: над собой, системой, пострадавшим?
4. Какие сведения об авторской позиции действительно есть?

**Ловушка:** знание внутренней шутки может показывать знакомство с культурой, но не устанавливает политическую позицию, характер или диагноз зрителя. Одного репоста также недостаточно, чтобы без контекста приписать человеку буквальное содержание надписи.

### Самопроверка

Почему одинаковая картинка в двух чатах может получать разную реакцию? **Ответ:** различаются аудитория, общий опыт и ситуация применения, а не только пиксели.

[Оригинальная полоса KC Green](https://gunshowcomic.com/648); [источник кадра-шаблона](https://github.com/jacebrowning/memegen/tree/main/templates/fine). Это фрагмент настоящей работы автора, не генерация ИИ.',updated_at=now() FROM course_sections s JOIN courses c ON c.id=s.course_id WHERE p.section_id=s.id AND c.title IN ('Мемология: история и теория мемов','Мемология с ИИ: история и теория мемов') AND p.type='theory' AND p.title='Мемы как социальный язык';

